<script setup lang="ts">
import type { Project } from '~~/shared/types/projects'
import { estimateFinancials, estimateDetailsSchema } from '~~/shared/utils/estimate'
const props = defineProps<{ project: Project }>()
const { query, save } = useProjectEstimateData(() => props.project.id)
const details = computed(() => query.data.value?.details ?? estimateDetailsSchema.parse({}))
const financials = computed(() => estimateFinancials({ items: query.data.value?.items ?? [], details: details.value }))
const open = ref(false), busy = ref(false), error = ref(''), revision = ref(0), draft = ref(estimateDetailsSchema.parse({})), notes = ref('')
const editable = computed(() => props.project.permission !== 'viewer')
const money = (value: number) => value.toLocaleString('ru-RU', { minimumFractionDigits: 2, maximumFractionDigits: 2 })+' ₽'
function show() { draft.value = JSON.parse(JSON.stringify(details.value)); notes.value = details.value.notes.join('\n'); revision.value = query.data.value?.revision ?? 0; error.value = ''; open.value = true }
async function submit() {
  if (!editable.value || busy.value) return
  error.value = ''; const parsed = estimateDetailsSchema.safeParse({ ...draft.value, notes: notes.value.split('\n').map(note => note.trim()).filter(Boolean) })
  if (!parsed.success) { error.value = parsed.error.issues[0]?.message || 'Проверьте поля'; return }
  busy.value = true
  try { await save(revision.value, { details: parsed.data }); open.value = false }
  catch (failure: any) { error.value = failure?.data?.message || failure.message }
  finally { busy.value = false }
}
watch(editable, allowed => { if (!allowed) open.value = false })
</script>
<template>
  <section class="estimate-project-details" aria-label="Параметры и результат сметы"><div class="details-heading"><div><h2>{{ details.description || 'Параметры сметы' }}</h2><p>{{ [details.title, details.code].filter(Boolean).join(' / ') || 'Тираж, цена для клиента и финансовый результат проекта' }}</p></div><UButton v-if="editable" label="Параметры сметы" icon="i-lucide-settings-2" color="neutral" variant="outline" @click="show"/></div><dl class="details-facts"><div><dt>Тираж, компл.</dt><dd>{{ details.batchQuantity.toLocaleString('ru-RU') }}</dd></div><div><dt>Цена набора для клиента, ₽</dt><dd>{{ money(details.clientUnitPrice) }}</dd></div><div><dt>Финишная дата</dt><dd>{{ details.finishDate ? details.finishDate.split('-').reverse().join('.') : '—' }}</dd></div><div><dt>НДС в выручке</dt><dd>{{ details.revenueVatRate }}% · включён в цену</dd></div></dl><div class="details-financials"><div><small>ИТОГО ЗАТРАТЫ</small><strong>{{ money(financials.cost) }}</strong><span>Входящий НДС: {{ money(financials.inputVat) }}</span><span>Без НДС: {{ money(financials.netCost) }}</span></div><div><small>ВЫРУЧКА ПО ДОГОВОРУ</small><strong>{{ money(financials.revenue) }}</strong><span>НДС: {{ money(financials.outputVat) }}</span><span>Без НДС: {{ money(financials.netRevenue) }}</span></div><div><small>Результат без НДС, после прямых затрат</small><strong>{{ money(financials.profit) }}</strong><span>Разница с НДС: {{ money(financials.difference) }}</span><span>Рентабельность: {{ financials.profitability === null ? '—' : (financials.profitability * 100).toLocaleString('ru-RU', { maximumFractionDigits: 2 })+'%' }}</span></div></div></section>
  <UModal v-model:open="open" title="Параметры сметы" description="Поля шапки и пояснения для экспорта по шаблону." :dismissible="!busy" :ui="{ content: 'sm:max-w-3xl' }"><template #body><form id="estimate-details-form" class="details-form" @submit.prevent="submit"><label>Название в шапке<input v-model="draft.title" maxlength="160" :disabled="busy" placeholder="Например, ЛЕНСВЕТ"/></label><label>Код проекта<input v-model="draft.code" maxlength="80" :disabled="busy" placeholder="LS-2026-10"/></label><label class="full">Проект<input v-model="draft.description" maxlength="500" :disabled="busy"/></label><label>Тираж, компл.<input v-model.number="draft.batchQuantity" type="number" min="0" max="1000000" step="any" required :disabled="busy"/></label><label>Цена набора для клиента, ₽<input v-model.number="draft.clientUnitPrice" type="number" min="0" step="0.01" required :disabled="busy"/></label><label>Финишная дата<input v-model="draft.finishDate" type="date" :disabled="busy"/></label><label>НДС в выручке, %<input v-model.number="draft.revenueVatRate" type="number" min="0" max="100" step="0.01" required :disabled="busy"/></label><label class="full">Подзаголовок сметы<textarea v-model="draft.notice" maxlength="1000" :disabled="busy"/></label><label class="full">Примечания сметы, каждое с новой строки<textarea v-model="notes" rows="3" :disabled="busy"/></label><label class="full">Примечание к реквизитам<textarea v-model="draft.counterpartyNote" maxlength="2000" :disabled="busy"/></label><UAlert v-if="error" color="error" :description="error" class="full"/></form></template><template #footer><div class="details-footer"><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="open = false"/><UButton type="submit" form="estimate-details-form" label="Сохранить параметры" :loading="busy"/></div></template></UModal>
</template>
<style scoped>
.estimate-project-details{margin:24px 0 32px}.details-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:20px}.details-heading h2{font-size:20px;font-weight:600;color:#334155}.details-heading p{font-size:13px;color:#94a3b8;margin-top:8px}.details-facts{display:flex;gap:20px 36px;flex-wrap:wrap;margin:24px 0}.details-facts dt{font-size:12px;color:#94a3b8}.details-facts dd{font-size:14px;color:#475569;margin-top:6px}.details-financials{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.details-financials>div{background:white;border:1px solid #e2e8f0;border-radius:18px;padding:22px;display:flex;gap:8px;flex-direction:column}.details-financials small{font-size:11px;color:#94a3b8;min-height:28px}.details-financials strong{font-size:23px;color:#334155;margin:4px 0 8px}.details-financials span{font-size:12px;color:#8292a8}.details-form{display:grid;grid-template-columns:1fr 1fr;gap:20px}.details-form label{display:flex;flex-direction:column;gap:8px;font-size:13px;color:#475569}.details-form input,.details-form textarea{background:white;border:1px solid #cbd5e1;border-radius:8px;padding:10px 12px;width:100%;min-width:0;outline-color:var(--ui-primary)}.details-form .full{grid-column:1/-1}.details-footer{display:flex;gap:12px;justify-content:flex-end;width:100%}@media(max-width:750px){.details-financials{grid-template-columns:1fr}.details-heading{flex-direction:column}.details-form{grid-template-columns:1fr}}
</style>
